    "myprofile": "<div class=\"topbar\">\n            <div class=\"search-box\">\n                <i class=\"fa-solid fa-magnifying-glass\"></i>\n                <input type=\"text\" id=\"searchProfile\" placeholder=\"Search employee profile...\">\n            </div>\n\n            <div class=\"notification\" id=\"notificationBtn\">\n                <i class=\"fa-regular fa-bell\"></i>\n                <span class=\"notification-badge\">8</span>\n\n                <div class=\"notification-panel\" id=\"notificationPanel\">\n                    <div class=\"notification-header\">\n                        <h3>Notifications</h3>\n                        <i class=\"fa-solid fa-ellipsis\"></i>\n                    </div>\n\n                    <div class=\"notification-tabs\">\n                        <button class=\"active\">All</button>\n                        <button>Unread</button>\n                    </div>\n\n                    <div class=\"notification-list\">\n                        <div class=\"notification-item\">\n                            <div class=\"notification-avatar\">🍰</div>\n                            <div>\n                                <h4>New order received</h4>\n                                <p>2 minutes ago</p>\n                            </div>\n                        </div>\n\n                        <div class=\"notification-item\">\n                            <div class=\"notification-avatar\">👩</div>\n                            <div>\n                                <h4>Alice completed order #1052</h4>\n                                <p>10 minutes ago</p>\n                            </div>\n                        </div>\n\n                        <div class=\"notification-item\">\n                            <div class=\"notification-avatar\">⚠️</div>\n                            <div>\n                                <h4>Low stock: Croissant</h4>\n                                <p>Today</p>\n                            </div>\n                        </div>\n\n                        <div class=\"notification-item\">\n                            <div class=\"notification-avatar\">⭐</div>\n                            <div>\n                                <h4>Customer left 5-star review</h4>\n                                <p>Yesterday</p>\n                            </div>\n                        </div>\n                    </div>\n\n                    <button class=\"view-all-btn\">View all notifications</button>\n                </div>\n            </div>\n        </div>\n\n        <section class=\"page-header\">\n            <div>\n                <h1>My Profile</h1>\n                <p>View bakery employee information, performance and recent activities.</p>\n            </div>\n        </section>\n\n        <section class=\"profile-page-layout\">\n\n            <div class=\"profile-card profile-summary-card\">\n                <img id=\"profileAvatar\" class=\"profile-main-avatar\" src=\"\" alt=\"Employee Avatar\">\n\n                <h2 id=\"profileName\"></h2>\n                <p id=\"profileRole\"></p>\n\n                <span id=\"profileStatus\" class=\"member-status online\"></span>\n\n                <div class=\"profile-mini-info\">\n                    <div>\n                        <strong id=\"profileEmployeeId\"></strong>\n                        <span>Employee ID</span>\n                    </div>\n\n                    <div>\n                        <strong id=\"profileBranch\"></strong>\n                        <span>Branch</span>\n                    </div>\n\n                    <div>\n                        <strong id=\"profileShift\"></strong>\n                        <span>Shift</span>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"profile-card\">\n                <h2>Employee Information</h2>\n\n                <div class=\"profile-info-grid\">\n                    <div>\n                        <label>Email</label>\n                        <p id=\"profileEmail\"></p>\n                    </div>\n\n                    <div>\n                        <label>Phone</label>\n                        <p id=\"profilePhone\"></p>\n                    </div>\n\n                    <div>\n                        <label>Gender</label>\n                        <p id=\"profileGender\"></p>\n                    </div>\n\n                    <div>\n                        <label>Birthday</label>\n                        <p id=\"profileBirthday\"></p>\n                    </div>\n\n                    <div>\n                        <label>Hire Date</label>\n                        <p id=\"profileHireDate\"></p>\n                    </div>\n\n                    <div>\n                        <label>Address</label>\n                        <p id=\"profileAddress\"></p>\n                    </div>\n                </div>\n\n                <div class=\"profile-bio\">\n                    <label>Bio</label>\n                    <p id=\"profileBio\"></p>\n                </div>\n            </div>\n\n        </section>\n\n        <section class=\"profile-stats-grid\">\n            <div class=\"profile-stat-card\">\n                <i class=\"fa-solid fa-receipt\"></i>\n                <div>\n                    <h3 id=\"statOrders\"></h3>\n                    <p>Total Orders</p>\n                </div>\n            </div>\n\n            <div class=\"profile-stat-card\">\n                <i class=\"fa-solid fa-sack-dollar\"></i>\n                <div>\n                    <h3 id=\"statRevenue\"></h3>\n                    <p>Monthly Revenue</p>\n                </div>\n            </div>\n\n            <div class=\"profile-stat-card\">\n                <i class=\"fa-solid fa-star\"></i>\n                <div>\n                    <h3 id=\"statRating\"></h3>\n                    <p>Customer Rating</p>\n                </div>\n            </div>\n\n            <div class=\"profile-stat-card\">\n                <i class=\"fa-solid fa-calendar-check\"></i>\n                <div>\n                    <h3 id=\"statAttendance\"></h3>\n                    <p>Attendance</p>\n                </div>\n            </div>\n        </section>\n\n        <section class=\"profile-bottom-grid\">\n\n            <div class=\"profile-card\">\n                <h2>Skills</h2>\n                <div id=\"skillsList\"></div>\n            </div>\n\n            <div class=\"profile-card\">\n                <h2>Recent Activities</h2>\n                <div id=\"activitiesList\"></div>\n            </div>\n\n        </section>"
